// Hansoft: committed instead of generated by CMake's GENERATE_EXPORT_HEADER.
// Malterlib builds xlnt as a static library from cached CMake imports, so configure (which wrote this file
// into the source tree) doesn't run on build machines. Equivalent to the generated output for a static build.

#ifndef XLNT_API_H
#define XLNT_API_H

#ifndef XLNT_API
#  define XLNT_API
#endif

#ifndef XLNT_CMAKE_NO_EXPORT
#  define XLNT_CMAKE_NO_EXPORT
#endif

#ifndef XLNT_DEPRECATED
#  if defined(_MSC_VER)
#    define XLNT_DEPRECATED __declspec(deprecated)
#  else
#    define XLNT_DEPRECATED __attribute__ ((__deprecated__))
#  endif
#endif

#ifndef XLNT_DEPRECATED_EXPORT
#  define XLNT_DEPRECATED_EXPORT XLNT_API XLNT_DEPRECATED
#endif

#ifndef XLNT_DEPRECATED_NO_EXPORT
#  define XLNT_DEPRECATED_NO_EXPORT XLNT_CMAKE_NO_EXPORT XLNT_DEPRECATED
#endif

#endif /* XLNT_API_H */
